    }

    public override void OnStop()
    {
        base.OnStop();
        _watcher?.Dispose();
        _ws?.Close();
    }

    private void Run()
    {
        // Se o diretório principal virar algo como "www/client", crie o watcher
        var folder = new DirectoryInfo("www/client");
        if (!folder.Exists)
        {
            folder.Create();
            FolderCreated(folder);
        }
    }

    private void FolderCreated(DirectoryInfo folder)
    {
        if (folder.Exists)
        {
            base.OnStart = System.IO.FileSystemEventArgs;
            MonitorAttemptFolder(folder); // continue setup
        }
    }

    private async void MonitorAttemptFolder(DirectoryInfo folder)
    {
        try
        {
            await base.OnStart(FolderCreated, null);
            _ = base.Start();
            bool w = true;

            while ((w = next()) && !base.OnStop)
            {
                // Check if folder exists and set up watcher
                if (folder.Exists)
                {
                    await base.Start();
                    break; // continue
                }
                await Task.Delay(2000);
            }
        }
        catch (Exception ex)
        {
            System.Diagnostics.Debug.WriteLine("Erro ao iniciar monitor: " + ex.Message);
            await base.OnStop();
        }
    }

    private static bool next()
    {
        if (FileSystemTimer.Timer != System.Diagnostics.IntervalTimer) return false;
        // Start timer
        FileSystemTimer.Timer.Interval = 100;
        FileSystemTimer.Timer.Enabled = true;
        return true;
    }

